new file mode 100644
index 000000000..42b26b937
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,32 @@
+// Usage (from the repo root): node repro/check.js [path/to/typescript.js]
+// Exits 1 while the displayed type of `Test` is wrong, 0 once it is `{ prop1: "hello"; }`.
+const path = require("path");
+const tsPath = path.resolve(process.argv[2] || path.join(__dirname, "..", "built", "local", "typescript.js"));
+const ts = require(tsPath);
+
+const file = path.join(__dirname, "check.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [] });
+const checker = program.getTypeChecker();
+
+// The input must itself be error-free; otherwise the check would be measuring something else.
+const diagnostics = ts.getPreEmitDiagnostics(program);
+if (diagnostics.length) {
+    console.error("check.ts has unexpected diagnostics:\n" + ts.formatDiagnostics(diagnostics, {
+        getCanonicalFileName: f => f, getCurrentDirectory: () => process.cwd(), getNewLine: () => "\n",
+    }));
+    process.exit(2);
+}
+
+const sourceFile = program.getSourceFile(file);
+const alias = sourceFile.statements.find(s => ts.isTypeAliasDeclaration(s) && s.name.text === "Test");
+const actual = checker.typeToString(checker.getTypeAtLocation(alias.name), undefined, ts.TypeFormatFlags.NoTruncation);
+const expected = '{ prop1: "hello"; }';
+
+console.log(`TypeScript ${ts.version}`);
+console.log(`expected: type Test = ${expected}`);
+console.log(`actual:   type Test = ${actual}`);
+if (actual !== expected) {
+    console.error("FAIL: Test is not displayed as the unwrapped type");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/repro/check.ts b/repro/check.ts
new file mode 100644
index 000000000..20bc93175
--- /dev/null
+++ b/repro/check.ts
@@ -0,0 +1,25 @@
+// Reproduction input: inline type assertion inside a generic call argument.
+// Expected: `Test` is displayed as `{ prop1: "hello"; }` (TypeScript 5.6.3 behavior).
+// Actual (5.7+): `Test` is displayed as `{ prop1: Wrapper<"hello">; }`.
+
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+
+type Test = Unwrap<typeof value>
